function [m] = rotor_geometry(a0, g, gi, nr, ng)
%ROTOR_GEOMETRY  The geometry of nr rotors of spin axes a0 on the gimbals gi (1-based, 0 on none) of ng gimbals of axes g.
%   a0: real[1][3][DYN_NR] (passed a plain number)
%   g: real[1][3][DYN_NG] (passed a plain number)
%   gi: int[DYN_NR] (passed a whole number)
%   nr: int (passed a whole number)
%   ng: int (passed a whole number)
%   returns m: RotorGeometry (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = asils.models.rotors.RotorGeometry_zero();
    a = zeros(8, 3);
    t0 = zeros(8, 3);
    gg = zeros(4, 3);
    gix = zeros(8, 1);
    for ir = (0):((nr) - 1)
        a((ir) + 1, :) = (a0((ir) + 1, :)).'.';
        gix((ir) + 1) = gi((ir) + 1);
        if (gi((ir) + 1) > 0)
            t0((ir) + 1, :) = [g(((gi((ir) + 1) - 1)) + 1, 2)*a0((ir) + 1, 3) - g(((gi((ir) + 1) - 1)) + 1, 3)*a0((ir) + 1, 2); g(((gi((ir) + 1) - 1)) + 1, 3)*a0((ir) + 1, 1) - g(((gi((ir) + 1) - 1)) + 1, 1)*a0((ir) + 1, 3); g(((gi((ir) + 1) - 1)) + 1, 1)*a0((ir) + 1, 2) - g(((gi((ir) + 1) - 1)) + 1, 2)*a0((ir) + 1, 1)].';
        end
    end
    for jg = (0):((ng) - 1)
        gg((jg) + 1, :) = (g((jg) + 1, :)).'.';
    end
    m = asils.models.rotors.RotorGeometry_zero();
    m.nr = nr;
    m.ng = ng;
    m.a0 = a;
    m.t0 = t0;
    m.g = gg;
    m.gi = gix;
end
